import type { GameView } from '../lib/game/models/Game.types';

export const inventoryViewConfig: GameView = {
	id: 'inventory',
	title: 'Inventory',
	dimension: '2d',
	style: '',
	checkpoints: []
};

import type { GameState, GameInput } from '../lib/game/models/Game.types';

export function dash(state: Readonly<GameState>, input: Readonly<GameInput>): GameState {
	void state;
	void input;
	return {};
}

import { expect, test } from 'vitest';
import { dash } from '../src/utils/dash';

test('dash produces an independent state patch', () => {
	expect(dash({}, { x: 0, y: 0 })).toEqual({});
});

